mutation uploadAudio($input: AudioUploadInput) {
	uploadAudio(input: $input) {
		success
		title
		message
	}
}

query User($userId: String!) 
{
    user(id: $userId) 
    {
        user_id
        recent_transcript
        recent_meeting
        num_transcripts
        name
        minutes_consumed
        is_admin
        integrations
        email
        user_groups 
        {
            name
            handle
        }
    }
}
